package com.aistock.scheduler.alert;
import static com.aistock.scheduler.alert.AlertJobRecords.*;
import com.aistock.common.BusinessException;import java.time.*;import java.util.*;import java.sql.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.TransactionDefinition;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.stereotype.Repository;import org.springframework.http.HttpStatus;
@Repository public class AlertJobRepository {
 private final JdbcTemplate jdbc;private final Clock clock;private final TransactionTemplate tx;
 private static final Set<String> RETRY=Set.of("SOURCE_UNAVAILABLE","SOURCE_TIMEOUT","SOURCE_BUSY","ATTEMPT_EXPIRED","ALERT_DEPENDENCY_UNAVAILABLE","ALERT_BOUNDARY_CHANGED","ALERT_EVIDENCE_UNAVAILABLE","ALERT_EVALUATION_UNAVAILABLE","ALERT_CALENDAR_UNAVAILABLE","ALERT_RAW_UNAVAILABLE","MARKET_REVISION_CONFLICT");
 public AlertJobRepository(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);}
 public Job enqueue(Input i){validate(i);String identity=identity(i),key=hash(identity+"|"+i.roundId()),active=hash(identity);return tx.execute(s->{try{jdbc.update("insert into alert_job(job_id,job_key,active_key,rule_id,rule_revision,instrument_id,trade_date,raw_version_id,round_id,work_key,stage,state,attempt_count,next_at,created_at,updated_at) values(?,?,?,?,?,?,?,?,?,?,'PREPARE_EVIDENCE','QUEUED',0,?,?,?)",UUID.randomUUID().toString(),key,active,i.ruleId().toString(),i.revision(),i.instrumentId(),i.tradeDate(),i.rawVersionId().toString(),i.roundId(),workKey(i),ts(clock.instant()),ts(clock.instant()),ts(clock.instant()));}catch(org.springframework.dao.DuplicateKeyException duplicate){/* unique job or unresolved identity already owns dispatch */}var rows=jdbc.query("select * from alert_job where job_key=? or active_key=? order by created_at limit 1 for update",this::map,key,active);if(rows.isEmpty())throw invalid();return rows.get(0);});}
 public Job get(UUID id){var rows=jdbc.query("select * from alert_job where job_id=?",this::map,id.toString());if(rows.isEmpty())throw invalid();return rows.get(0);}
 public Claim claim(Instant now){return tx.execute(s->{expire(now);var candidates=jdbc.query("select j.* from alert_job j where j.state in('QUEUED','RETRY_WAIT') and j.next_at<=? and (j.stage<>'PREPARE_EVIDENCE' or not exists(select 1 from alert_evidence_work w where w.work_key=j.work_key and (w.state='RUNNING' or (w.state='RETRY_WAIT' and w.next_at>?)))) order by j.next_at,j.created_at,j.job_id limit 50 for update skip locked",this::map,ts(now),ts(now));for(var j:candidates){int ordinal=j.attempts()+1;
   if("PREPARE_EVIDENCE".equals(j.stage())){
    var i=j.input();String key=workKey(i);jdbc.update("insert into alert_evidence_work(work_key,instrument_id,raw_version_id,trade_date,round_id,state,attempt_count,next_at,updated_at) values(?,?,?,?,?,'READY',0,?,?) on duplicate key update work_key=work_key",key,i.instrumentId(),i.rawVersionId().toString(),i.tradeDate(),i.roundId(),ts(now),ts(now));var w=jdbc.queryForMap("select * from alert_evidence_work where work_key=? for update",key);String state=(String)w.get("state");
    if("AVAILABLE".equals(state)&&now.isBefore(((Timestamp)w.get("cache_until")).toInstant())){jdbc.update("update alert_job set evidence_id=?,stage='EVALUATE_RULE',state='QUEUED',attempt_count=0,error_code=null,next_at=?,updated_at=? where job_id=?",w.get("evidence_id"),ts(now),ts(now),j.id().toString());continue;}
    if("RUNNING".equals(state))continue;
    if("RETRY_WAIT".equals(state)&&now.isBefore(((Timestamp)w.get("next_at")).toInstant()))continue;
    if("FAILED".equals(state)&&(!now.isBefore(((Timestamp)w.get("next_at")).toInstant())&&!i.roundId().equals(w.get("round_id")))){state="READY";jdbc.update("update alert_evidence_work set state='READY',attempt_count=0,round_id=?,evidence_id=null,cache_until=null where work_key=?",i.roundId(),key);}
    if("FAILED".equals(state)){String reason=(String)w.get("error_code");terminal(j,"SKIPPED_STALE".equals(reason)?"SKIPPED":"FAILED",reason,now);continue;}
    ordinal="RETRY_WAIT".equals(state)?((Number)w.get("attempt_count")).intValue()+1:1;
   }
   UUID operation=UUID.randomUUID();Instant until=now.plusSeconds(120).truncatedTo(java.time.temporal.ChronoUnit.MILLIS);
   jdbc.update("update alert_job set state='RUNNING',attempt_count=?,current_attempt=?,lease_until=?,next_at=?,updated_at=? where job_id=?",ordinal,operation.toString(),ts(until),ts(now.plusSeconds(10)),ts(now),j.id().toString());
   int attemptNo=Objects.requireNonNull(jdbc.queryForObject("select count(*) from alert_job_attempt where job_id=?",Integer.class,j.id().toString()))+1;
   jdbc.update("insert into alert_job_attempt(attempt_id,job_id,ordinal,stage,state,lease_until,started_at) values(?,?,?,?,'RUNNING',?,?)",operation.toString(),j.id().toString(),attemptNo,j.stage(),ts(until),ts(now));
   if("PREPARE_EVIDENCE".equals(j.stage()))jdbc.update("update alert_evidence_work set state='RUNNING',operation_id=?,lease_until=?,attempt_count=?,error_code=null,evidence_id=null,cache_until=null,updated_at=? where work_key=?",operation.toString(),ts(until),ordinal,ts(now),workKey(j.input()));
   return new Claim(j.id(),operation,j.stage(),j.input(),j.evidenceId(),until);
  }return null;});}
 public List<Claim> pendingReceipts(){return tx.execute(s->{var now=clock.instant();expire(now);return jdbc.query("select j.*,a.attempt_id,a.stage attempt_stage,a.lease_until attempt_lease from alert_job j join alert_job_attempt a on a.attempt_id=j.current_attempt where j.state in('RUNNING','RECONCILING') and j.next_at<=? order by j.next_at,j.job_id limit 1",(r,n)->new Claim(UUID.fromString(r.getString("job_id")),UUID.fromString(r.getString("attempt_id")),r.getString("attempt_stage"),input(r),uuid(r.getString("evidence_id")),r.getTimestamp("attempt_lease").toInstant()),ts(now));});}
 public void unknown(Claim c){tx.executeWithoutResult(s->{var j=locked(c.jobId());if(!matches(j,c))return;jdbc.update("update alert_job set state='RECONCILING',next_at=?,error_code='RESULT_UNKNOWN',updated_at=? where job_id=?",ts(clock.instant().plusSeconds(10)),ts(clock.instant()),c.jobId().toString());jdbc.update("update alert_job_attempt set state='UNKNOWN',error_code='RESULT_UNKNOWN' where attempt_id=? and state='RUNNING'",c.attemptId().toString());});}
 public boolean saveEvidence(Claim c,UUID evidence){return resolve(c,new Result(c.attemptId(),"AVAILABLE",evidence,null),false);}
 public boolean finish(Claim c,Result result){return resolve(c,result,false);}
 public boolean reconcile(Claim c,Result result){return resolve(c,result,true);}
 private boolean resolve(Claim c,Result result,boolean confirmed){validateResult(c,result);if("RUNNING".equals(result.state()))return false;return Boolean.TRUE.equals(tx.execute(s->{var j=locked(c.jobId());if(!matches(j,c)||!confirmed&&!clock.instant().isBefore(c.leaseUntil()))return false;var now=clock.instant();String state=result.state(),error=result.errorCode();
   if("PREPARE_EVIDENCE".equals(c.stage())){
    var work=jdbc.queryForMap("select * from alert_evidence_work where work_key=? for update",workKey(j.input()));if(!c.attemptId().toString().equals(work.get("operation_id"))||!"RUNNING".equals(work.get("state")))return false;
    if("AVAILABLE".equals(state)){jdbc.update("update alert_evidence_work set state='AVAILABLE',evidence_id=?,cache_until=?,error_code=null,updated_at=? where work_key=?",result.referenceId().toString(),ts(now.plusSeconds(300)),ts(now),workKey(j.input()));endAttempt(c,"SUCCEEDED",null,result.referenceId(),now);jdbc.update("update alert_job set stage='EVALUATE_RULE',state='QUEUED',attempt_count=0,evidence_id=?,current_attempt=null,lease_until=null,error_code=null,next_at=?,updated_at=? where job_id=?",result.referenceId().toString(),ts(now),ts(now),j.id().toString());return true;}
    if("SKIPPED_STALE".equals(state)){endAttempt(c,"SKIPPED",null,null,now);jdbc.update("update alert_evidence_work set state='FAILED',error_code='SKIPPED_STALE',next_at=?,updated_at=? where work_key=?",ts(now.plusSeconds(300)),ts(now),workKey(j.input()));terminal(j,"SKIPPED","SKIPPED_STALE",now);return true;}
    boolean retry=j.attempts()<3&&RETRY.contains(error);Instant next=now.plusSeconds(retry?(j.attempts()==1?60:120):300);jdbc.update("update alert_evidence_work set state=?,error_code=?,next_at=?,updated_at=? where work_key=?",retry?"RETRY_WAIT":"FAILED",error,ts(next),ts(now),workKey(j.input()));fail(j,c,error,retry,next,now);return true;
   }
   if(Set.of("TRIGGERED","ALREADY_TRIGGERED","NOT_MET").contains(state)){endAttempt(c,"SUCCEEDED",null,result.referenceId(),now);terminal(j,"SUCCEEDED",null,now);return true;}
   if(state.startsWith("SKIPPED_")){endAttempt(c,"SKIPPED",error,null,now);terminal(j,"SKIPPED",error,now);return true;}
   boolean retry=j.attempts()<3&&("EVIDENCE_UNAVAILABLE".equals(state)||RETRY.contains(error));fail(j,c,error,retry,now.plusSeconds(j.attempts()==1?60:120),now);return true;
  }));}
 private void fail(Job j,Claim c,String error,boolean retry,Instant next,Instant now){endAttempt(c,"FAILED",error,null,now);if(retry)jdbc.update("update alert_job set state='RETRY_WAIT',current_attempt=null,lease_until=null,error_code=?,next_at=?,updated_at=? where job_id=?",error,ts(next),ts(now),j.id().toString());else terminal(j,"FAILED",error,now);}
 private void terminal(Job j,String state,String error,Instant now){jdbc.update("update alert_job set state=?,active_key=null,current_attempt=null,lease_until=null,error_code=?,updated_at=? where job_id=?",state,error,ts(now),j.id().toString());}
 private void endAttempt(Claim c,String state,String error,UUID reference,Instant now){jdbc.update("update alert_job_attempt set state=?,error_code=?,reference_id=?,finished_at=? where attempt_id=? and state in('RUNNING','UNKNOWN')",state,error,reference==null?null:reference.toString(),ts(now),c.attemptId().toString());}
 private void expire(Instant now){var rows=jdbc.queryForList("select job_id,current_attempt from alert_job where state='RUNNING' and lease_until<=? limit 50 for update skip locked",ts(now));for(var row:rows){jdbc.update("update alert_job set state='RECONCILING',error_code='RESULT_UNKNOWN',next_at=?,updated_at=? where job_id=?",ts(now),ts(now),row.get("job_id"));jdbc.update("update alert_job_attempt set state='UNKNOWN',error_code='RESULT_UNKNOWN' where attempt_id=? and state='RUNNING'",row.get("current_attempt"));}}
 private Job locked(UUID id){return jdbc.queryForObject("select * from alert_job where job_id=? for update",this::map,id.toString());}
 private boolean matches(Job j,Claim c){if(!Set.of("RUNNING","RECONCILING").contains(j.state())||!j.stage().equals(c.stage())||!j.input().equals(c.input()))return false;var rows=jdbc.queryForList("select current_attempt,lease_until from alert_job where job_id=?",j.id().toString());var row=rows.get(0);return c.attemptId().toString().equals(row.get("current_attempt"))&&c.leaseUntil().equals(((Timestamp)row.get("lease_until")).toInstant());}
 private Job map(ResultSet r,int n)throws SQLException{return new Job(UUID.fromString(r.getString("job_id")),input(r),uuid(r.getString("evidence_id")),r.getString("stage"),r.getString("state"),r.getInt("attempt_count"),r.getTimestamp("next_at").toInstant(),r.getString("error_code"));}
 private Input input(ResultSet r)throws SQLException{return new Input(UUID.fromString(r.getString("rule_id")),r.getLong("rule_revision"),r.getString("instrument_id"),r.getDate("trade_date").toLocalDate(),UUID.fromString(r.getString("raw_version_id")),r.getString("round_id"));}
 private void validate(Input i){if(i==null||i.ruleId()==null||i.revision()<0||i.instrumentId()==null||!i.instrumentId().matches("(SH|SZ)[0-9]{6}")||i.tradeDate()==null||i.tradeDate().isBefore(LocalDate.of(1990,1,1))||i.tradeDate().isAfter(clock.instant().atZone(ZoneId.of("Asia/Shanghai")).toLocalDate())||i.rawVersionId()==null||i.roundId()==null||!i.roundId().matches("[A-Za-z0-9_-]{1,64}"))throw invalid();}
 private void validateResult(Claim c,Result r){if(c==null||r==null||!c.attemptId().equals(r.operationId())||r.state()==null||r.errorCode()!=null&&!r.errorCode().matches("[A-Z0-9_]{1,64}"))throw invalid();String state=r.state();if("RUNNING".equals(state)){if(r.referenceId()!=null||r.errorCode()!=null)throw invalid();return;}if("PREPARE_EVIDENCE".equals(c.stage())){if("AVAILABLE".equals(state)){if(r.referenceId()==null||r.errorCode()!=null)throw invalid();}else if("FAILED".equals(state)){if(r.referenceId()!=null||r.errorCode()==null)throw invalid();}else if("SKIPPED_STALE".equals(state)){if(r.referenceId()!=null||r.errorCode()!=null&&!"ALERT_DATE_NOT_LATEST".equals(r.errorCode()))throw invalid();}else throw invalid();}else{if(Set.of("TRIGGERED","ALREADY_TRIGGERED").contains(state)){if(r.referenceId()==null||r.errorCode()!=null)throw invalid();}else if("NOT_MET".equals(state)||Set.of("SKIPPED_RULE_CHANGED","SKIPPED_INACTIVE","SKIPPED_NOT_EFFECTIVE","SKIPPED_STALE").contains(state)){if(r.referenceId()!=null)throw invalid();}else if(Set.of("FAILED","EVIDENCE_UNAVAILABLE").contains(state)){if(r.referenceId()!=null||r.errorCode()==null)throw invalid();}else throw invalid();}}
 private static String identity(Input i){return i.ruleId()+"|"+i.revision()+"|"+i.instrumentId()+"|"+i.tradeDate()+"|"+i.rawVersionId();}
 private static String workKey(Input i){return hash(i.instrumentId()+"|"+i.rawVersionId()+"|"+i.tradeDate());}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("SHA-256 unavailable");}}
 private static UUID uuid(String value){return value==null?null:UUID.fromString(value);}private static Timestamp ts(Instant value){return Timestamp.from(value);}
 private static BusinessException invalid(){return new BusinessException("ALERT_JOB_INVALID","预警任务或回执未通过核验",HttpStatus.BAD_REQUEST);}
}
